package net.officefloor.hq.app.role;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** Roles by sheet: at most one per user name; a name with none is a clerk. */
@Repository
public class RoleRepository {

    private static final RowMapper<Role> ROW = (rs, i) -> new Role(rs.getString("sheet_id"),
            rs.getString("user_name"), rs.getString("role"));

    private final JdbcTemplate jdbc;

    public RoleRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's assigned roles, by user name. */
    public List<Role> list(String sheetId) {
        return jdbc.query("SELECT * FROM sheet_role WHERE sheet_id = ? ORDER BY user_name", ROW, sheetId);
    }

    /** The role the user acts in on the sheet: steward while a delegation to them is in force by the sheet's
     *  today, else the one assigned. */
    public String of(String sheetId, String user) {
        Integer delegated = jdbc.queryForObject("SELECT COUNT(*) FROM sheet_delegation d JOIN sheet s "
                + "ON s.id = d.sheet_id WHERE d.sheet_id = ? AND d.user_name = ? "
                + "AND s.today BETWEEN d.from_date AND d.to_date", Integer.class, sheetId, user);
        return delegated != null && delegated > 0 ? Role.STEWARD : assigned(sheetId, user);
    }

    /** The user's assigned role on the sheet: the one assigned, else clerk. */
    public String assigned(String sheetId, String user) {
        List<String> found = jdbc.queryForList("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                String.class, sheetId, user);
        return found.isEmpty() ? Role.CLERK : found.get(0);
    }

    /** Assign the user's role on the sheet, replacing any they had. */
    public Role set(String sheetId, String user, String role) {
        jdbc.update("MERGE INTO sheet_role KEY (sheet_id, user_name) VALUES (?, ?, ?)", sheetId, user, role);
        return new Role(sheetId, user, role);
    }
}
package net.officefloor.hq.app.delegation;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** Delegations of the steward role by sheet. One is in force while the sheet's today is inside its dates. */
@Repository
public class DelegationRepository {

    private static final RowMapper<Delegation> ROW = (rs, i) -> new Delegation(rs.getLong("id"),
            rs.getString("sheet_id"), rs.getString("user_name"), rs.getObject("from_date", LocalDate.class),
            rs.getObject("to_date", LocalDate.class), rs.getString("delegated_by"));

    private final JdbcTemplate jdbc;

    public DelegationRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's delegations, in the order they were made. */
    public List<Delegation> list(String sheetId) {
        return jdbc.query("SELECT * FROM sheet_delegation WHERE sheet_id = ? ORDER BY id", ROW, sheetId);
    }

    public Delegation add(String sheetId, DelegationInput input) {
        jdbc.update("INSERT INTO sheet_delegation (sheet_id, user_name, from_date, to_date, delegated_by) "
                + "VALUES (?, ?, ?, ?, ?)", sheetId, input.name(), input.from(), input.to(), input.user());
        Long id = jdbc.queryForObject("SELECT MAX(id) FROM sheet_delegation WHERE sheet_id = ?", Long.class, sheetId);
        return new Delegation(id, sheetId, input.name(), input.from(), input.to(), input.user());
    }

    /** The steward whose delegation to the user is in force by the sheet's today (the latest made, when several
     *  are), or null when none is. */
    public String delegator(String sheetId, String user) {
        List<String> found = jdbc.queryForList("SELECT d.delegated_by FROM sheet_delegation d "
                + "JOIN sheet s ON s.id = d.sheet_id WHERE d.sheet_id = ? AND d.user_name = ? "
                + "AND s.today BETWEEN d.from_date AND d.to_date ORDER BY d.id DESC", String.class, sheetId, user);
        return found.isEmpty() ? null : found.get(0);
    }
}
